insert into kafaa_value_chains (id, code, name_en, name_ar, summary_en, summary_ar, stages, facts, skill_ids, lane_ids, pathway_ids, cec_ids, benchmark_ids, sources, status, as_of, sort) values
('vc-hydrogen', 'VC-1', 'Hydrogen', 'الهيدروجين', 'Clean electricity, and for some designs heat, can split water into hydrogen for industrial users. This explainer covers the chain and its skills only; no ENEC project or site is implied.', 'يمكن للكهرباء النظيفة، وللحرارة في بعض التصاميم، فصل الماء لإنتاج الهيدروجين للمستخدمين الصناعيين. يغطي هذا الشرح السلسلة ومهاراتها فقط، ولا يُفهم منه أي مشروع أو موقع للمؤسسة.', '[{"key":"source","en":"Low-carbon electricity and heat","ar":"كهرباء وحرارة منخفضتا الكربون","role_en":"A nuclear plant supplies steady low-carbon electricity; some reactor designs could also supply high-temperature heat.","role_ar":"توفر المحطة النووية كهرباء ثابتة منخفضة الكربون؛ ويمكن لبعض تصاميم المفاعلات أيضاً توفير حرارة عالية."},{"key":"conversion","en":"Electrolysis","ar":"التحليل الكهربائي","role_en":"Electrolysers split water into hydrogen and oxygen; high-temperature electrolysis uses heat to need less electricity.","role_ar":"تفصل أجهزة التحليل الكهربائي الماء إلى هيدروجين وأكسجين؛ ويستخدم التحليل عالي الحرارة الحرارة ليحتاج إلى كهرباء أقل."},{"key":"storage","en":"Storage and transport","ar":"التخزين والنقل","role_en":"Hydrogen is compressed, stored or converted (for example to ammonia) before it moves; safety distances and codes matter here.","role_ar":"يُضغط الهيدروجين أو يُخزَّن أو يُحوَّل (إلى الأمونيا مثلاً) قبل نقله؛ وهنا تهم مسافات السلامة والمعايير."},{"key":"use","en":"Industrial users","ar":"المستخدمون الصناعيون","role_en":"Fertiliser, steel and refining can replace fossil hydrogen; the interface stays outside the plant safety boundary.","role_ar":"يمكن لصناعات الأسمدة والصلب والتكرير استبدال الهيدروجين الأحفوري؛ وتبقى الواجهة خارج حدود السلامة للمحطة."}]'::jsonb, '[{"id":"vc-h2-f1","en":"At least 16.6 million renewable-energy jobs existed worldwide in 2024; growth slowed to 2.3% despite record capacity additions.","ar":"بلغت وظائف الطاقة المتجددة في العالم 16.6 مليون وظيفة على الأقل في 2024، وتباطأ نموها إلى 2.3% رغم إضافات قياسية في القدرة.","label":"EU BUILD UP · IRENA and ILO, Renewable Energy and Jobs: Annual Review 2025","url":"https://build-up.ec.europa.eu/en/resources-and-tools/publications/annual-review-2025-renewable-energy-and-jobs","as_of":"2026-10-10","published":"2025","secondary":true},{"id":"vc-h2-f2","en":"IRENA and the ILO call for education and training at scale against shortages, particularly in digital skills and manufacturing.","ar":"تدعو آيرينا ومنظمة العمل الدولية إلى توسيع التعليم والتدريب لمواجهة النقص، ولا سيما في المهارات الرقمية والتصنيع.","label":"EU BUILD UP · IRENA and ILO, Renewable Energy and Jobs: Annual Review 2025","url":"https://build-up.ec.europa.eu/en/resources-and-tools/publications/annual-review-2025-renewable-energy-and-jobs","as_of":"2026-10-10","published":"2025","secondary":true},{"id":"vc-h2-f3","en":"The OECD-NEA''s Plan 2035 builds the nuclear workforce in support of tripling nuclear capacity by 2050.","ar":"تبني خطة 2035 لوكالة الطاقة النووية القوى العاملة النووية دعماً لمضاعفة القدرة النووية ثلاث مرات بحلول 2050.","label":"OECD-NEA · Plan 2035 vision paper: Scaling Technology, Growing Careers, Securing the Future (Oct 2025)","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf","as_of":"2026-10-10","published":"2025-10","secondary":false}]'::jsonb, array['sk-fs-gr-h2heat','sk-fs-gr-lifecycle']::text[], array['lane-hydrogen','lane-netzero']::text[], array['pw-et-system-integration','pw-gr-h2heat-l1']::text[], array['cec-3-2','cec-2-2']::text[], array['ENERGY-JOBS','NEA']::text[], '[{"id":"fs42-irena-jobs","label":"EU BUILD UP · IRENA and ILO, Renewable Energy and Jobs: Annual Review 2025","url":"https://build-up.ec.europa.eu/en/resources-and-tools/publications/annual-review-2025-renewable-energy-and-jobs","as_of":"2026-10-10"},{"id":"fs42-nea-plan2035","label":"OECD-NEA · Plan 2035 vision paper: Scaling Technology, Growing Careers, Securing the Future (Oct 2025)","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf","as_of":"2026-10-10"}]'::jsonb, 'active', '2026-10-10', 1),
('vc-process-heat', 'VC-2', 'Process heat', 'الحرارة الصناعية', 'Reactor heat, not only electricity, could serve industrial processes such as desalination or chemicals. Concept learning only; no deployment decision implied.', 'يمكن لحرارة المفاعل، لا الكهرباء وحدها، أن تخدم عمليات صناعية مثل التحلية أو الكيماويات. تعلّم مفاهيمي فقط، ولا يُفهم منه أي قرار بالنشر.', '[{"key":"source","en":"Heat source","ar":"مصدر الحرارة","role_en":"Light-water reactors give steam at moderate temperature; high-temperature and molten-salt designs give hotter heat.","role_ar":"تعطي مفاعلات الماء الخفيف بخاراً بحرارة متوسطة؛ وتعطي التصاميم عالية الحرارة وتصاميم الأملاح المنصهرة حرارة أعلى."},{"key":"loop","en":"Heat transport loop","ar":"دائرة نقل الحرارة","role_en":"An intermediate loop (steam, gas or molten salt) carries heat away and keeps the plant separated from the user.","role_ar":"تنقل دائرة وسيطة (بخار أو غاز أو أملاح منصهرة) الحرارة وتُبقي المحطة منفصلة عن المستخدم."},{"key":"process","en":"Industrial process","ar":"العملية الصناعية","role_en":"Desalination, district heat and chemical processes use the heat; each temperature range suits different users.","role_ar":"تستخدم التحلية والتدفئة المركزية والعمليات الكيميائية الحرارة؛ ويناسب كل نطاق حراري مستخدمين مختلفين."},{"key":"safety","en":"Safety boundary","ar":"حدود السلامة","role_en":"Coupling a reactor to an industrial user needs a safety case that covers both sides of the interface.","role_ar":"يحتاج ربط مفاعل بمستخدم صناعي إلى حالة سلامة تغطي جانبي الواجهة."}]'::jsonb, '[{"id":"vc-ph-f1","en":"In the IEA Energy Employment Survey, 60% of companies reported labour shortages, worst in technical trades such as pipefitters, plant operators and nuclear specialists.","ar":"في مسح الوكالة الدولية للطاقة للتوظيف في قطاع الطاقة، أفادت 60% من الشركات بنقص في العمالة، وكان أشدّه في المهن الفنية مثل مركّبي الأنابيب ومشغلي المحطات والمتخصصين النوويين.","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10","published":"2025-12","secondary":true},{"id":"vc-ph-f2","en":"To avoid further skill misalignment by 2030, graduates entering the energy sector must rise by about 40% globally.","ar":"لتجنّب مزيد من عدم التوافق في المهارات بحلول 2030، يجب أن يرتفع عدد الخريجين الداخلين إلى قطاع الطاقة بنحو 40% عالمياً.","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10","published":"2025-12","secondary":true},{"id":"vc-ph-f3","en":"The IEA warns that skills shortages have contributed to increased outages and reduced output in several advanced nuclear fleets.","ar":"تحذّر الوكالة الدولية للطاقة من أن نقص المهارات أسهم في زيادة فترات الانقطاع وتراجع الإنتاج في عدة أساطيل نووية متقدمة.","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10","published":"2025-12","secondary":true}]'::jsonb, array['sk-fs-gr-h2heat','sk-fs-tr-systems']::text[], array['lane-hydrogen','lane-advanced']::text[], array['pw-et-system-integration','pw-gr-h2heat-l2']::text[], array['cec-3-2','cec-2-1']::text[], array['ENERGY-JOBS','NEA']::text[], '[{"id":"fs42-iea-wee","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10"}]'::jsonb, 'active', '2026-10-10', 2),
('vc-grid', 'VC-3', 'Grid integration', 'التكامل مع الشبكة', 'Firm low-carbon power works alongside solar, storage and flexible demand to keep the grid balanced. This explainer covers the system and its skills; it makes no ENEC project claim.', 'تعمل الطاقة الثابتة منخفضة الكربون جنباً إلى جنب مع الطاقة الشمسية والتخزين والطلب المرن للحفاظ على توازن الشبكة. يغطي هذا الشرح المنظومة ومهاراتها، ولا يتضمن أي ادعاء بمشروع للمؤسسة.', '[{"key":"generation","en":"Generation","ar":"التوليد","role_en":"Large reactors run at steady output and provide firm low-carbon power alongside variable solar.","role_ar":"تعمل المفاعلات الكبيرة بإنتاج ثابت وتوفر طاقة ثابتة منخفضة الكربون إلى جانب الطاقة الشمسية المتغيرة."},{"key":"flexibility","en":"Flexible operation","ar":"التشغيل المرن","role_en":"Some fleets follow load; flexibility has limits set by fuel, chemistry and equipment.","role_ar":"تتبع بعض الأساطيل الحمل؛ وللمرونة حدود يفرضها الوقود والكيمياء والمعدات."},{"key":"network","en":"Transmission and distribution","ar":"النقل والتوزيع","role_en":"The network carries power to users and depends on skilled electricians and line workers.","role_ar":"تنقل الشبكة الكهرباء إلى المستخدمين وتعتمد على كهربائيين وعمال خطوط مهرة."},{"key":"balance","en":"Demand and storage","ar":"الطلب والتخزين","role_en":"Batteries, storage and demand response balance supply and demand; hydrogen can store surplus power.","role_ar":"توازن البطاريات والتخزين والاستجابة للطلب بين العرض والطلب؛ ويمكن للهيدروجين تخزين الكهرباء الفائضة."}]'::jsonb, '[{"id":"vc-gr-f1","en":"The energy sector employed 76 million people in 2024, 5 million more than in 2019, growing about twice as fast as the global economy.","ar":"وظّف قطاع الطاقة 76 مليون شخص في 2024، بزيادة 5 ملايين عن 2019، بنمو يقارب ضعف نمو الاقتصاد العالمي.","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10","published":"2025-12","secondary":true},{"id":"vc-gr-f2","en":"Among technical trades, the IEA reports shortages of electricians and line workers alongside plant operators.","ar":"من بين المهن الفنية، تشير الوكالة الدولية للطاقة إلى نقص في الكهربائيين وعمال الخطوط إلى جانب مشغلي المحطات.","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10","published":"2025-12","secondary":true},{"id":"vc-gr-f3","en":"Employers in the WEF Future of Jobs Report 2025 name the green transition a top driver of change; environmental stewardship entered the ten fastest-growing skills for the first time.","ar":"يرى أصحاب العمل في تقرير مستقبل الوظائف 2025 للمنتدى الاقتصادي العالمي أن التحول الأخضر من أبرز محركات التغيير؛ ودخلت رعاية البيئة قائمة أسرع عشر مهارات نمواً لأول مرة.","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10","published":"2025-01","secondary":true}]'::jsonb, array['sk-fs-gr-grid','sk-fs-tr-systems']::text[], array['lane-grid']::text[], array['pw-et-system-integration','pw-gr-grid-l1']::text[], array['cec-3-2','cec-2-1']::text[], array['ENERGY-JOBS','NEA']::text[], '[{"id":"fs42-iea-wee","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', '2026-10-10', 3)
insert into kafaa_transition_tracks (id, feature, pathway_id, credential_code, max_hours, audience_en, audience_ar, summary_en, summary_ar, chain_ids, benchmark_ids, sources, sort) values
('tt-system-integration', 'FS42', 'pw-et-system-integration', 'MC-H2-HEAT', null, 'Engineers, strategy staff and interested employees', 'المهندسون وموظفو الاستراتيجية والموظفون المهتمون', 'An awareness-to-practitioner route through the hydrogen, process-heat and grid value chains, with curated readings, a study gig, practice with engineering and chemistry, and the matching horizon lanes.', 'مسار من الوعي إلى الممارسة عبر سلاسل القيمة للهيدروجين والحرارة الصناعية والشبكة، مع قراءات منتقاة، ومهمة دراسية قصيرة، وممارسة مع الهندسة والكيمياء، والمسارات المستقبلية المطابقة.', array['vc-hydrogen','vc-process-heat','vc-grid']::text[], array['ENERGY-JOBS','NEA']::text[], '[{"id":"fs42-nea-plan2035","label":"OECD-NEA · Plan 2035 vision paper: Scaling Technology, Growing Careers, Securing the Future (Oct 2025)","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf","as_of":"2026-10-10"},{"id":"fs42-iea-wee","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10"},{"id":"fs42-irena-jobs","label":"EU BUILD UP · IRENA and ILO, Renewable Energy and Jobs: Annual Review 2025","url":"https://build-up.ec.europa.eu/en/resources-and-tools/publications/annual-review-2025-renewable-energy-and-jobs","as_of":"2026-10-10"}]'::jsonb, 1),
('tt-esg-managers', 'FS43', 'pw-et-esg-managers', 'MC-CLEAN-ENERGY', 10, 'Managers, finance and reporting staff', 'المديرون وموظفو المالية وإعداد التقارير', 'A shared baseline for managers who report on sustainability and human capital, completable in under 10 hours at about one hour a week.', 'أساس مشترك للمديرين الذين يعدّون تقارير الاستدامة ورأس المال البشري، يمكن إكماله في أقل من 10 ساعات بمعدل ساعة أسبوعياً تقريباً.', '{}'::text[], array['GREENCOMP','ISO30414','ENERGY-JOBS']::text[], '[{"id":"fs43-iso30414","label":"ISO TC 260 · ISO 30414:2025, strengthening human capital reporting (24 Aug 2025)","url":"https://committee.iso.org/sites/tc260/home/news/content-left-area/news-and-updates/iso-30414-2025-strengthening-hum.html","as_of":"2026-10-10"},{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 2)
insert into kafaa_credit_tags (id, item_kind, item_id, title_en, title_ar, nqf_level, notional_hours, credits, indicative, basis_en, basis_ar, stack_ids, status, listed, source_url, as_of, version, updated_by, updated_at) values
('ct:course:c-et-esg-clinic', 'course', 'c-et-esg-clinic', 'ESG data clinic: your team''s numbers', 'عيادة بيانات الحوكمة البيئية والاجتماعية: أرقام فريقك', 3, 3, 0.3, true, '2 contact hours x 1.5 for study and practice; level from the course''s skill objectives (Kafa''a level 1).', '2 ساعة تواصل × 1.5 للدراسة والممارسة؛ المستوى مأخوذ من أهداف المهارات في الدورة (مستوى كفاءة 1).', '{}'::text[], 'published', true, 'https://uaelegislation.gov.ae/en/legislations/2615/download', '2026-10-10', 1, 'p-training-mgr', '2026-10-10T09:00:00Z'),
('ct:course:c-et-ghg-mgr', 'course', 'c-et-ghg-mgr', 'GHG and ESG basics for managers', 'أساسيات غازات الدفيئة والحوكمة البيئية والاجتماعية للمديرين', 3, 6, 0.6, true, '3 contact hours x 2 for study and practice; level from the course''s skill objectives (Kafa''a level 1).', '3 ساعة تواصل × 2 للدراسة والممارسة؛ المستوى مأخوذ من أهداف المهارات في الدورة (مستوى كفاءة 1).', '{}'::text[], 'published', true, 'https://uaelegislation.gov.ae/en/legislations/2615/download', '2026-10-10', 1, 'p-training-mgr', '2026-10-10T09:00:00Z'),
('ct:pathway:pw-et-esg-managers', 'pathway', 'pw-et-esg-managers', 'ESG and GHG literacy for managers', 'الإلمام بالحوكمة البيئية والاجتماعية وغازات الدفيئة للمديرين', 3, 5, 0.5, true, 'Practice and project component only (40% of 3 months at 1 h a week); the pathway''s courses count separately.', 'مكوّن الممارسة والمشروع فقط (40% من 3 أشهر بمعدل 1 ساعة أسبوعياً)؛ تُحتسب دورات المسار بشكل منفصل.', array['st-clean-energy']::text[], 'published', true, 'https://uaelegislation.gov.ae/en/legislations/2615/download', '2026-10-10', 1, 'p-training-mgr', '2026-10-10T09:00:00Z'),
('ct:pathway:pw-et-system-integration', 'pathway', 'pw-et-system-integration', 'Energy-system integration: from awareness to practitioner', 'تكامل منظومة الطاقة: من الوعي إلى الممارسة', 4, 19, 1.9, true, 'Practice and project component only (40% of 6 months at 2 h a week); the pathway''s courses count separately.', 'مكوّن الممارسة والمشروع فقط (40% من 6 أشهر بمعدل 2 ساعة أسبوعياً)؛ تُحتسب دورات المسار بشكل منفصل.', array['st-clean-energy']::text[], 'published', true, 'https://uaelegislation.gov.ae/en/legislations/2615/download', '2026-10-10', 1, 'p-training-mgr', '2026-10-10T09:00:00Z')
